package com.rudel.reborn;
import android.app.Activity;
import android.os.Bundle;
import android.widget.*;
import android.graphics.drawable.GradientDrawable;
import com.google.firebase.auth.*;
import com.google.firebase.firestore.*;
import java.util.*;
public class ConnectActivity extends Activity {
 FirebaseFirestore db=FirebaseFirestore.getInstance(); String uid; LinearLayout root,body; TextView status; ListenerRegistration a,b; int generation;
 int dp(int x){return (int)(x*getResources().getDisplayMetrics().density);}
 Map<String,Object> data(Object... v){Map<String,Object> m=new HashMap<>();for(int i=0;i<v.length;i+=2)m.put((String)v[i],v[i+1]);return m;}
 void text(LinearLayout l,String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextColor(0xffeef3ff);t.setTextSize(size);t.setPadding(0,dp(8),0,dp(8));l.addView(t);}
 void button(LinearLayout l,String s,Runnable r){Button x=new Button(this);x.setText(s);x.setAllCaps(false);x.setTextColor(-1);GradientDrawable g=new GradientDrawable();g.setColor(0xff334779);g.setCornerRadius(dp(18));x.setBackground(g);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(48));p.setMargins(0,dp(5),0,dp(5));l.addView(x,p);x.setOnClickListener(v->r.run());}
 EditText field(String hint){EditText e=new EditText(this);e.setHint(hint);e.setTextColor(-1);e.setHintTextColor(0xffaab8d0);body.addView(e);return e;}
 void clear(){generation++;if(a!=null)a.remove();if(b!=null)b.remove();a=b=null;body.removeAllViews();status.setText("");}
 void result(com.google.android.gms.tasks.Task<?> t){status.setText(t.isSuccessful()?"Saved":"Failed: check connection or permissions");}
 @Override public void onCreate(Bundle s){super.onCreate(s);FirebaseUser u=FirebaseAuth.getInstance().getCurrentUser();if(u==null){finish();return;}uid=u.getUid();ScrollView sc=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(20),dp(20),dp(20),dp(20));root.setBackgroundColor(0xff090f21);sc.setFillViewport(true);sc.addView(root);setContentView(sc);text(root,"RUDEL / CONNECT",28);button(root,"Friends & messages",this::friends);button(root,"Stories",this::stories);status=new TextView(this);status.setTextColor(0xff82e7db);root.addView(status);body=new LinearLayout(this);body.setOrientation(1);root.addView(body);friends();}
 void friends(){clear();text(body,"Your circle",24);text(body,"Share only a nickname. Connect with people you know.",14);EditText h=field("Unique nickname (a-z, 0-9, _)");button(body,"Reserve nickname",()->{String n=h.getText().toString().trim().toLowerCase(Locale.ROOT);if(!n.matches("[a-z0-9_]{3,24}")){status.setText("Use 3–24 valid characters");return;}db.collection("handles").document(n).set(data("uid",uid)).addOnCompleteListener(this,this::result);});EditText q=field("Friend's exact nickname");button(body,"Send friend request",()->{String n=q.getText().toString().trim().toLowerCase(Locale.ROOT);if(!n.matches("[a-z0-9_]{3,24}"))return;db.collection("handles").document(n).get().addOnSuccessListener(this,d->{String to=d.getString("uid");if(to==null||to.equals(uid)){status.setText("No matching friend");return;}db.collection("invites").document(uid+"_"+to).set(data("from",uid,"to",to,"accepted",false)).addOnCompleteListener(this,this::result);}).addOnFailureListener(this,e->status.setText("Search failed"));});LinearLayout incoming=new LinearLayout(this),outgoing=new LinearLayout(this);incoming.setOrientation(1);outgoing.setOrientation(1);body.addView(incoming);body.addView(outgoing);a=db.collection("invites").whereEqualTo("to",uid).addSnapshotListener(this,(s,e)->{if(e!=null){status.setText("Requests unavailable");return;}renderInvites(incoming,s,true);});b=db.collection("invites").whereEqualTo("from",uid).addSnapshotListener(this,(s,e)->{if(e==null)renderInvites(outgoing,s,false);});}
 void renderInvites(LinearLayout l,QuerySnapshot s,boolean incoming){l.removeAllViews();text(l,incoming?"Incoming":"Sent",20);if(s==null)return;for(DocumentSnapshot d:s){boolean ok=Boolean.TRUE.equals(d.getBoolean("accepted"));String peer=d.getString(incoming?"from":"to");text(l,"Member "+(peer==null?"":peer.substring(0,Math.min(8,peer.length())))+(ok?" · Connected":" · Pending"),15);if(ok)button(l,"Open private chat",()->chat(d.getId()));else if(incoming)button(l,"Accept",()->d.getReference().update("accepted",true).addOnCompleteListener(this,this::result));button(l,"Remove connection",()->d.getReference().delete().addOnCompleteListener(this,this::result));}}
 void chat(String id){clear();text(body,"Private messages",24);text(body,"Only accepted connection members can read messages. Not end-to-end encrypted.",14);EditText e=field("Message");CollectionReference c=db.collection("invites").document(id).collection("messages");button(body,"Send",()->{String v=e.getText().toString().trim();if(v.isEmpty()||v.length()>1000)return;c.add(data("uid",uid,"text",v,"createdAt",FieldValue.serverTimestamp())).addOnCompleteListener(this,t->{result(t);if(t.isSuccessful())e.setText("");});});LinearLayout list=new LinearLayout(this);list.setOrientation(1);body.addView(list);a=c.orderBy("createdAt",Query.Direction.DESCENDING).limit(50).addSnapshotListener(this,(s,err)->{if(err!=null){status.setText("Chat unavailable");return;}list.removeAllViews();if(s!=null)for(DocumentSnapshot d:s)text(list,(uid.equals(d.getString("uid"))?"You: ":"Friend: ")+d.getString("text"),17);});}
 void stories(){clear();text(body,"Stories / 24h",24);text(body,"Text stories visible to signed-in members. Avoid personal details.",14);EditText e=field("Write a story");button(body,"Publish",()->{String v=e.getText().toString().trim();if(v.isEmpty()||v.length()>500)return;db.collection("stories").add(data("uid",uid,"text",v,"createdAt",FieldValue.serverTimestamp())).addOnCompleteListener(this,t->{result(t);if(t.isSuccessful())e.setText("");});});LinearLayout list=new LinearLayout(this);list.setOrientation(1);body.addView(list);a=db.collection("stories").orderBy("createdAt",Query.Direction.DESCENDING).limit(50).addSnapshotListener(this,(s,err)->{if(err!=null){status.setText("Stories unavailable");return;}list.removeAllViews();if(s!=null)for(DocumentSnapshot d:s){com.google.firebase.Timestamp t=d.getTimestamp("createdAt");if(t==null||System.currentTimeMillis()-t.toDate().getTime()>86400000L)continue;text(list,d.getString("text"),18);if(uid.equals(d.getString("uid")))button(list,"Delete my story",()->d.getReference().delete().addOnCompleteListener(this,this::result));}});}
 @Override protected void onDestroy(){if(a!=null)a.remove();if(b!=null)b.remove();super.onDestroy();}
}
